package com.pocketwise;
import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean; import org.springframework.security.crypto.password.PasswordEncoder; import com.pocketwise.model.AppUser; import com.pocketwise.repository.UserRepository;
@SpringBootApplication public class StudentExpenseManagerApplication { public static void main(String[] args){SpringApplication.run(StudentExpenseManagerApplication.class,args);} @Bean CommandLineRunner seedAdmin(UserRepository users,PasswordEncoder encoder){return args->{String email=System.getenv().getOrDefault("ADMIN_EMAIL","admin@mrfintech.local");String password=System.getenv().getOrDefault("ADMIN_PASSWORD","MRFintech@2026");if(!users.existsByEmailIgnoreCase(email)){AppUser a=new AppUser();a.setName("MR Fintech Administrator");a.setEmail(email);a.setPassword(encoder.encode(password));a.setRole("ADMIN");users.save(a);}};}}
